-- public.extend_reason(p_world uuid, p_uid uuid, p_x integer, p_y integer, p_into integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.extend_reason(p_world uuid, p_uid uuid, p_x integer, p_y integer, p_into integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_slab foundation; v_deck int; b building; v_why text;
begin
  if not on_my_deed(p_world, p_uid, p_x, p_y) then return 'Only on your own settlement.'; end if;
  if is_token(p_world, p_x, p_y) then return 'Settlement totem here.'; end if;
  if building_at(p_world, p_x, p_y) is not null then return 'Already part of a building.'; end if;
  if aqueduct_over(p_world, p_x, p_y) then return 'Aqueduct over that tile.'; end if;
  -- gates: nor over the end of a bridge thrown across, whose winch or landing stands there (`BRIDGE_END_HERE`).
  if bridge_end_at(p_world, p_x, p_y) then return 'Bridge end on this tile.'; end if;
  select * into b from building where world_id = p_world and id = p_into;
  select * into v_slab from foundation f where f.world_id = p_world and f.x = p_x and f.y = p_y;
  if v_slab.world_id is not null then
    if land_tile(p_world, p_x, p_y) <> tile_id('Packed dirt') then return 'Needs packed dirt.'; end if;
    if not bill_done(v_slab.needed) then return 'Foundation not poured yet.'; end if;
    if v_slab.pool then return 'Not in a pool.'; end if;
    if b.deck is not null and v_slab.top <> b.deck then
      return 'Slab at ' || metres(v_slab.top) || ' m; ' || b.name || ' floor at ' || metres(b.deck) || ' m'
        || '. Must match.';
    end if;
  else
    v_deck := pier_deck_for(p_world, p_uid, p_x, p_y, p_into);
    if v_deck is null then
      if land_tile(p_world, p_x, p_y) <> tile_id('Packed dirt') then return 'Needs packed dirt.'; end if;
    else
      v_why := coalesce(pier_refusal(p_world, p_x, p_y, v_deck), pier_site_refusal(p_world, p_uid, p_x, p_y));
      if v_why is not null then return v_why; end if;
    end if;
  end if;
  if exists (select 1 from item i where i.world_id = p_world and i.holder = 'ground' and i.gx = p_x and i.gy = p_y) then
    return 'Items on the tile: clear them first.';
  end if;
  return null;
end $function$
